UPDATE CORRESPONSALES.USUARIO
SET USR_PASWORD = :hash, USR_IS_CLAVE_TEMPORAL = 0, USR_ESTADO = 1, USR_INTENTOS_PIN = 0
WHERE USR_CODIGO = :usr_codigo;
COMMIT;

UPDATE CORRESPONSALES.USUARIO
SET USR_INTENTOS = 0, USR_ESTADO = 1, USR_INTENTOS_PIN = 0
WHERE USR_USUARIO = :usuario;
COMMIT;

UPDATE CORRESPONSALES.Usuario
SET CODIGO_SUCURSAL = :codigo_sucursal
WHERE Usr_Cedula = :cedula;
COMMIT;

UPDATE CORRESPONSALES.Pos
SET pos_mac = :nuevoMac
WHERE pos_id = :pos_id;
COMMIT;

SELECT c.cuen_saldo_disp - cr.cr_cta_cobrar
FROM fisja.cuentas c, corresponsales.corresponsalrepresentante cr
WHERE ...;

SELECT NVL(saldo.CXC_FINAL,0) - NVL(trx.total_movimientos,0)
FROM saldo_cuenta_diaria saldo, (...) trx
WHERE ...;

SELECT d.tco_codigo, descripcion, cantidad, observaciones
FROM CORRESPONSALES.ACTACOMPROBANTESDETALLE d
JOIN CORRESPONSALES.TIPOTRANSACCION t ON ...;

SELECT ACO_NUMERO, ACO_CODIGO, ACO_FECHA_DESDE, ACO_FECHA_HASTA
FROM ACTACOMPROBANTES
WHERE CR_ID = :cr_id;

SELECT * FROM CORRESPONSALES.TRANSACCION
WHERE trunc(TRANS_FECHA) = trunc(sysdate)
ORDER BY 1 DESC;

SELECT * FROM corresponsales.transaccion_comision
WHERE trunc(fecha) = trunc(sysdate)
ORDER BY fecha DESC;

INSERT INTO corresponsales.transaccion_reporte (codigo, codigo_tipo_transaccion, tipo_reporte, descripcion, usuario_registra, fecha_registra)
SELECT corresponsales.sqc_transaccion_reporte.nextval, tip_codigo, tipo_reporte, '', '3', SYSDATE
FROM corresponsales.tipotransaccion;

SELECT * FROM fisja.cabecera_comprob_conta -- o detalle_comprob_conta
WHERE trunc(com_fecha) = trunc(sysdate) AND codigo_transaccion = :codigo
ORDER BY com_fecha DESC;

BEGIN
  fisja.pk_transaccion.P_TRANSACCION(
    1,1,1,1,1,2,           -- empresa, actividad, tipo cliente, producto, moneda, concepto
    :cuenta, :cedula, :tipoTrx, '.', :valorEfectivo, 0,
    :observaciones, 1, 1, 'COOOPEANRRUV-06', 4.25, 1,
    vrn_numerotrx, vrv_codigoerror);
END;
COMMIT;

SELECT indice, texto_a, texto_b, entero_a, entero_b
FROM jst_servicios_virtuales.parametro
WHERE indice IN (:indices) AND codigo_empresa = 1;

SELECT * FROM JST_SERVICIOS_VIRTUALES.CORREO_ELECTRONICO
WHERE trunc(FECHA_USUARIO) = trunc(sysdate)
ORDER BY FECHA_USUARIO DESC;

UPDATE corresponsales.catalogo_mensajes
SET cm_respuesta_html = :texto
WHERE cm_id = :id;

GRANT SELECT, INSERT, UPDATE, DELETE
ON :esquema.:tabla
TO :rol;

INSERT INTO JST_SEGURIDADES.ROL_FORMA_ACCION
(CODIGO_ROL, CODIGO_FORMA, CODIGO_ACCION, ACTIVO, CODIGO_USUARIO_CREACION, FECHA_CREACION)
VALUES (:rol, :forma, :accion, 'S', :usuario, sysdate);

SELECT * FROM jst_seguridades.informacion_acceso
WHERE CODIGO_USUARIO = :codigo
ORDER BY 1 DESC;

SELECT * FROM CORRESPONSALES.LOG_SUCESOS_CORRESPONSALES
WHERE trunc(SUC_FECHA) = trunc(sysdate)
ORDER BY 1 DESC;
